contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We are the deployer of c, so this contract is the owner of c.
    // Call as owner: sendMoney may or may not revert; if it succeeds it performs an external call from C
    // but it should not increment depositsCount on C.
    function run(address target, uint value, bytes memory data) public payable {
        // If sendMoney will forward Ether from C, ensure this test has enough balance is unnecessary
        // because sendMoney transfers from C, not to C. No precondition needed.

        // Observe before state
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: calling sendMoney as owner cannot increase depositsCount.
        // So either the call reverted, or depositsCount stayed the same (did not increase).
        assert(reverted || afterDeposits == beforeDeposits);
    }

    receive() external payable {}
}

